import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { selectItems, UpdateItemAsync, DeleteItemAsync, } from '../features/cart/cartSlice';
import { Link, Navigate } from 'react-router-dom';
import { useForm } from "react-hook-form"
import { UpdateUserAsync } from '../features/user/userSlice';
// import { UpdateUserAsync } from '../features/auth/authSlice';
import { createOrderAsync, currentOrder } from '../features/order/orderSlice';
import { useAlert } from 'react-alert'
import { selectUserInfo } from '../features/user/userSlice';


export default function CheckOut() {
    const [open, setOpen] = useState(true)
    const products = useSelector(selectItems);
    const alert = useAlert()
    const currentorder = useSelector(currentOrder)
    const [SelectedAddress, setSelectedAddress] = useState()
    const [Payment, setPayment] = useState("Cash On Delivery");

    const totalCount = products.reduce((amount, e) => {
        return e.product.price * e.quantity + amount
    }, 0)
    const QuantityPerItem = products.reduce((total, e) => {
        return e.quantity + total
    }, 0)
    // const totalCount = products.reduce((amount, e) => {
    //     return e.price * e.quantity + amount
    // }, 0)
    // const QuantityPerItem = products.reduce((total, e) => {
    //     return e.quantity + total
    // }, 0)
    const dispatch = useDispatch()

    const handleChange = (e, Item) => {
        dispatch(UpdateItemAsync({ id: Item.id, quantity: +e.target.value }))
        console.log(products)
        // dispatch(UpdateItemAsync({ ...Item, quantity: +e.target.value }))
    }

    const handleDelete = (e, Item) => {
        dispatch(DeleteItemAsync(Item))
        console.log(Item)
    }
    const {
        register, handleSubmit, reset, formState: { errors },
    } = useForm();

    const user = useSelector(selectUserInfo)
    // const user = useSelector(selectLoggedIn)
    const handleAddress = (e) => {
        console.log(e.target.value);
        setSelectedAddress(user.addresses[e.target.value])
        // setSelectedAddress(user.addresses[e.target.value]);
    };
    const handlePayment = (e) => {
        console.log(e.target.value);
        setPayment(e.target.value)
        // setSelectedAddress(user.addresses[e.target.value]);
    };
    const handleOrder = () => {
        const order = { user: user.id, products, SelectedAddress, Payment, status: 'pending', quantity: QuantityPerItem, totalAmount: totalCount }
        dispatch(createOrderAsync(order))
    }



    return (

        <>
            {currentorder && currentorder.Payment === 'Cash On Delivery' && (<Navigate to={`/OrderSuccess/${currentorder.id}`} replace={true}></Navigate>)}
            {currentorder && currentorder.Payment === 'Net Banking' && (<Navigate to={`/PaymentIntent`} replace={true}></Navigate>)}
            {currentorder && currentorder.Payment === 'UPI' && (<Navigate to={`/ForgetPassword`} replace={true}></Navigate>)}

            <div className="min-h-screen bg-gray-50 py-8 sm:py-12">
                <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
                    <div className="grid grid-cols-1 gap-8 lg:grid-cols-12">

                        {/* Left Column - Forms */}
                        <div className="lg:col-span-7 xl:col-span-8">
                            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                                <div className="p-6 sm:p-8">
                                    <form noValidate onSubmit={handleSubmit((data) => {
                                        dispatch(UpdateUserAsync({ ...user, addresses: [...user.addresses, data] }))
                                        alert.success("New Address Added")
                                        reset();
                                        console.log(data)
                                    })} >
                                        <div className="space-y-8">
                                            {/* Personal Information Section */}
                                            <div className="border-b border-gray-200 pb-8">
                                                <div className="mb-6">
                                                    <h2 className="text-xl font-bold text-gray-900 tracking-tight">Personal Information</h2>
                                                    <p className="mt-2 text-sm text-gray-500">Use a permanent address where you can receive mail.</p>
                                                </div>

                                                <div className="grid grid-cols-1 gap-y-6 gap-x-6 sm:grid-cols-6">
                                                    <div className="sm:col-span-6">
                                                        <label htmlFor="fullname" className="block text-sm font-medium text-gray-700 mb-2">
                                                            Full name
                                                        </label>
                                                        <input
                                                            type="text"
                                                            id="fullname"
                                                            {...register("fullname", {
                                                                required: "Full name is required"
                                                            })}
                                                            className="block w-full rounded-lg border-gray-300 bg-gray-50 border px-4 py-3 text-gray-900 placeholder-gray-400 focus:border-indigo-500 focus:bg-white focus:ring-2 focus:ring-indigo-200 transition-all duration-200 sm:text-sm"
                                                            placeholder="Enter your full name"
                                                        />
                                                        {errors.fullname && <p className="mt-2 text-sm text-red-600 flex items-center gap-1"><span className="text-red-500">•</span> {errors.fullname.message}</p>}
                                                    </div>

                                                    <div className="sm:col-span-3">
                                                        <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                                                            Email address
                                                        </label>
                                                        <input
                                                            id="email"
                                                            type="email"
                                                            {...register("email", {
                                                                required: "Email is required",
                                                                pattern: {
                                                                    value: /\b[\w\.-]+@[\w\.-]+\.\w{2,4}\b/gi,
                                                                    message: "Please enter a valid email address"
                                                                }
                                                            })}
                                                            className="block w-full rounded-lg border-gray-300 bg-gray-50 border px-4 py-3 text-gray-900 placeholder-gray-400 focus:border-indigo-500 focus:bg-white focus:ring-2 focus:ring-indigo-200 transition-all duration-200 sm:text-sm"
                                                            placeholder="you@example.com"
                                                        />
                                                        {errors.email && <p className="mt-2 text-sm text-red-600 flex items-center gap-1"><span className="text-red-500">•</span> {errors.email.message}</p>}
                                                    </div>

                                                    <div className="sm:col-span-3">
                                                        <label htmlFor="phone" className="block text-sm font-medium text-gray-700 mb-2">
                                                            Phone number
                                                        </label>
                                                        <input
                                                            type="tel"
                                                            id="phone"
                                                            {...register("phone", {
                                                                required: "Phone number is required",
                                                                pattern: {
                                                                    value: /^[0-9]{10}$/,
                                                                    message: "Phone must be exactly 10 digits"
                                                                }
                                                            })}
                                                            className="block w-full rounded-lg border-gray-300 bg-gray-50 border px-4 py-3 text-gray-900 placeholder-gray-400 focus:border-indigo-500 focus:bg-white focus:ring-2 focus:ring-indigo-200 transition-all duration-200 sm:text-sm"
                                                            placeholder="1234567890"
                                                        />
                                                        {errors.phone && <p className="mt-2 text-sm text-red-600 flex items-center gap-1"><span className="text-red-500">•</span> {errors.phone.message}</p>}
                                                    </div>

                                                    <div className="sm:col-span-3">
                                                        <label htmlFor="country" className="block text-sm font-medium text-gray-700 mb-2">
                                                            Country
                                                        </label>
                                                        <select
                                                            id="country"
                                                            {...register("country", { required: "Country is required" })}
                                                            className="block w-full rounded-lg border-gray-300 bg-gray-50 border px-4 py-3 text-gray-900 focus:border-indigo-500 focus:bg-white focus:ring-2 focus:ring-indigo-200 transition-all duration-200 sm:text-sm"
                                                        >
                                                            <option value="">Select a country</option>
                                                            <option>India</option>
                                                            <option>Canada</option>
                                                            <option>Taiwan</option>
                                                        </select>
                                                    </div>

                                                    <div className="sm:col-span-6">
                                                        <label htmlFor="streetaddress" className="block text-sm font-medium text-gray-700 mb-2">
                                                            Street address
                                                        </label>
                                                        <input
                                                            type="text"
                                                            id="streetaddress"
                                                            {...register("streetaddress", { required: "Street address is required" })}
                                                            className="block w-full rounded-lg border-gray-300 bg-gray-50 border px-4 py-3 text-gray-900 placeholder-gray-400 focus:border-indigo-500 focus:bg-white focus:ring-2 focus:ring-indigo-200 transition-all duration-200 sm:text-sm"
                                                            placeholder="123 Main Street, Apt 4B"
                                                        />
                                                        {errors.streetaddress && <p className="mt-2 text-sm text-red-600 flex items-center gap-1"><span className="text-red-500">•</span> {errors.streetaddress.message}</p>}
                                                    </div>

                                                    <div className="sm:col-span-2">
                                                        <label htmlFor="city" className="block text-sm font-medium text-gray-700 mb-2">
                                                            City
                                                        </label>
                                                        <input
                                                            type="text"
                                                            id="city"
                                                            {...register("city", { required: "City is required" })}
                                                            className="block w-full rounded-lg border-gray-300 bg-gray-50 border px-4 py-3 text-gray-900 placeholder-gray-400 focus:border-indigo-500 focus:bg-white focus:ring-2 focus:ring-indigo-200 transition-all duration-200 sm:text-sm"
                                                            placeholder="City"
                                                        />
                                                        {errors.city && <p className="mt-2 text-sm text-red-600 flex items-center gap-1"><span className="text-red-500">•</span> {errors.city.message}</p>}
                                                    </div>

                                                    <div className="sm:col-span-2">
                                                        <label htmlFor="state" className="block text-sm font-medium text-gray-700 mb-2">
                                                            State / Province
                                                        </label>
                                                        <input
                                                            type="text"
                                                            id="state"
                                                            {...register("state", { required: "State is required" })}
                                                            className="block w-full rounded-lg border-gray-300 bg-gray-50 border px-4 py-3 text-gray-900 placeholder-gray-400 focus:border-indigo-500 focus:bg-white focus:ring-2 focus:ring-indigo-200 transition-all duration-200 sm:text-sm"
                                                            placeholder="State"
                                                        />
                                                        {errors.state && <p className="mt-2 text-sm text-red-600 flex items-center gap-1"><span className="text-red-500">•</span> {errors.state.message}</p>}
                                                    </div>

                                                    <div className="sm:col-span-2">
                                                        <label htmlFor="postalcode" className="block text-sm font-medium text-gray-700 mb-2">
                                                            ZIP / Postal code
                                                        </label>
                                                        <input
                                                            type="text"
                                                            id="postalcode"
                                                            {...register("postalcode", { required: "Postal code is required" })}
                                                            className="block w-full rounded-lg border-gray-300 bg-gray-50 border px-4 py-3 text-gray-900 placeholder-gray-400 focus:border-indigo-500 focus:bg-white focus:ring-2 focus:ring-indigo-200 transition-all duration-200 sm:text-sm"
                                                            placeholder="123456"
                                                        />
                                                        {errors.postalcode && <p className="mt-2 text-sm text-red-600 flex items-center gap-1"><span className="text-red-500">•</span> {errors.postalcode.message}</p>}
                                                    </div>
                                                </div>

                                                <div className="mt-8 flex items-center justify-end gap-x-4">
                                                    <button
                                                        type="button"
                                                        className="rounded-lg px-5 py-2.5 text-sm font-medium text-gray-700 hover:text-gray-900 hover:bg-gray-100 transition-colors duration-200"
                                                    >
                                                        Cancel
                                                    </button>
                                                    <button
                                                        type="submit"
                                                        className="rounded-lg bg-indigo-600 px-6 py-2.5 text-sm font-semibold text-white shadow-md hover:bg-indigo-700 hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 transition-all duration-200 transform hover:-translate-y-0.5"
                                                    >
                                                        Save Address
                                                    </button>
                                                </div>
                                            </div>

                                            {/* Address Selection Section */}
                                            <div className="border-b border-gray-200 pb-8">
                                                <div className="mb-6">
                                                    <h2 className="text-xl font-bold text-gray-900 tracking-tight">Select Delivery Address</h2>
                                                    <p className="mt-2 text-sm text-gray-500">Choose from your saved addresses.</p>
                                                </div>

                                                <div className="space-y-4">
                                                    <ul role="list" className="space-y-3">
                                                        {user && user.addresses.map((person, index) => (
                                                            <li
                                                                key={index}
                                                                className="relative flex items-start gap-4 rounded-xl border-2 border-gray-200 bg-white p-4 hover:border-indigo-300 hover:shadow-md transition-all duration-200 cursor-pointer group"
                                                            >
                                                                <div className="flex h-6 items-center mt-1">
                                                                    <input
                                                                        onChange={e => handleAddress(e)}
                                                                        id={`address-${index}`}
                                                                        name="address"
                                                                        type="radio"
                                                                        value={index}
                                                                        className="h-5 w-5 border-gray-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer"
                                                                    />
                                                                </div>
                                                                <div className="flex-1 min-w-0">
                                                                    <div className="flex items-center justify-between mb-1">
                                                                        <p className="text-base font-semibold text-gray-900">{person.fullname}</p>
                                                                        <span className="inline-flex items-center rounded-full bg-gray-100 px-2.5 py-0.5 text-xs font-medium text-gray-800">
                                                                            {person.postalcode}
                                                                        </span>
                                                                    </div>
                                                                    <p className="text-sm text-gray-600 mb-1">{person.email}</p>
                                                                    <p className="text-sm text-gray-600 mb-2">{person.phone}</p>
                                                                    <p className="text-sm text-gray-700 font-medium">
                                                                        {person.streetaddress}, {person.city}, {person.state}
                                                                    </p>
                                                                </div>
                                                            </li>
                                                        ))}
                                                    </ul>
                                                </div>
                                            </div>

                                            {/* Payment Method Section */}
                                            <div>
                                                <div className="mb-6">
                                                    <h2 className="text-xl font-bold text-gray-900 tracking-tight">Payment Method</h2>
                                                    <p className="mt-2 text-sm text-gray-500">Choose your preferred payment option.</p>
                                                </div>

                                                <fieldset className="space-y-4">
                                                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                                                        {[
                                                            { id: 'cod', value: 'Cash On Delivery', label: 'Cash On Delivery', desc: 'Pay when you receive' },
                                                            { id: 'netbanking', value: 'Net Banking', label: 'Net Banking', desc: 'Bank transfer' },
                                                            { id: 'upi', value: 'UPI', label: 'UPI', desc: 'Google Pay, PhonePe, etc.' }
                                                        ].map((method) => (
                                                            <div
                                                                key={method.id}
                                                                className={`relative flex flex-col rounded-xl border-2 p-4 cursor-pointer transition-all duration-200 ${Payment === method.value
                                                                        ? 'border-indigo-600 bg-indigo-50'
                                                                        : 'border-gray-200 hover:border-indigo-300 hover:bg-gray-50'
                                                                    }`}
                                                                onClick={() => setPayment(method.value)}
                                                            >
                                                                <div className="flex items-center gap-3 mb-2">
                                                                    <input
                                                                        onChange={handlePayment}
                                                                        id={method.id}
                                                                        name="payment-method"
                                                                        type="radio"
                                                                        checked={Payment === method.value}
                                                                        value={method.value}
                                                                        className="h-4 w-4 border-gray-300 text-indigo-600 focus:ring-indigo-500"
                                                                    />
                                                                    <label htmlFor={method.id} className="block text-sm font-semibold text-gray-900 cursor-pointer">
                                                                        {method.label}
                                                                    </label>
                                                                </div>
                                                                <p className="text-xs text-gray-500 ml-7">{method.desc}</p>
                                                            </div>
                                                        ))}
                                                    </div>
                                                </fieldset>
                                            </div>
                                        </div>
                                    </form>
                                </div>
                            </div>
                        </div>

                        {/* Right Column - Cart Summary */}
                        <div className="lg:col-span-5 xl:col-span-4">
                            <div className="sticky top-8">
                                <div className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden">
                                    <div className="bg-gray-900 px-6 py-4">
                                        <h2 className="text-lg font-bold text-white flex items-center gap-2">
                                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
                                            </svg>
                                            Order Summary
                                        </h2>
                                    </div>

                                    <div className="p-6">
                                        <div className="flow-root max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                                            <ul role="list" className="divide-y divide-gray-100">
                                                {products.length > 0 ? products.map((Item) => (
                                                    <li key={Item.id} className="flex py-4 group">
                                                        <div className="h-20 w-20 flex-shrink-0 overflow-hidden rounded-lg border border-gray-200 bg-gray-50 group-hover:border-indigo-300 transition-colors duration-200">
                                                            <img
                                                                src={Item.product.images[0]}
                                                                alt={Item.product.imageAlt || Item.product.title}
                                                                className="h-full w-full object-cover object-center"
                                                            />
                                                        </div>

                                                        <div className="ml-4 flex flex-1 flex-col">
                                                            <div>
                                                                <div className="flex justify-between text-sm font-medium text-gray-900">
                                                                    <h3 className="line-clamp-1 flex-1 mr-2">
                                                                        <a href={Item.href} className="hover:text-indigo-600 transition-colors">{Item.product.title}</a>
                                                                    </h3>
                                                                    <p className="text-indigo-600 font-semibold">₹{Item.product.price.toFixed(2)}</p>
                                                                </div>
                                                                <p className="mt-1 text-xs text-gray-500">{Item.product.color}</p>
                                                            </div>
                                                            <div className="flex flex-1 items-end justify-between text-sm">
                                                                <div className="flex items-center gap-2">
                                                                    <label htmlFor={`qty-${Item.id}`} className='text-xs font-medium text-gray-600'>
                                                                        Qty:
                                                                    </label>
                                                                    <select
                                                                        id={`qty-${Item.id}`}
                                                                        onChange={e => handleChange(e, Item)}
                                                                        value={Item.quantity}
                                                                        className="rounded-md border-gray-300 text-xs py-1 pl-2 pr-6 focus:border-indigo-500 focus:ring-indigo-500"
                                                                    >
                                                                        {[1, 2, 3, 4, 5].map(num => (
                                                                            <option key={num} value={num}>{num}</option>
                                                                        ))}
                                                                    </select>
                                                                </div>

                                                                <button
                                                                    onClick={e => handleDelete(e, Item)}
                                                                    type="button"
                                                                    className="text-xs font-medium text-red-600 hover:text-red-800 hover:underline transition-colors"
                                                                >
                                                                    Remove
                                                                </button>
                                                            </div>
                                                        </div>
                                                    </li>
                                                )) : (
                                                    <li className="py-12">
                                                        <div className="flex flex-col items-center justify-center text-center">
                                                            <svg className="w-16 h-16 text-gray-300 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
                                                            </svg>
                                                            <h3 className="text-lg font-medium text-gray-900 mb-1">Your cart is empty</h3>
                                                            <p className="text-sm text-gray-500">Add some items to get started</p>
                                                        </div>
                                                    </li>
                                                )}
                                            </ul>
                                        </div>

                                        {products.length > 0 && (
                                            <div className="mt-6 border-t border-gray-200 pt-6 space-y-4">
                                                <div className="flex justify-between text-sm text-gray-600">
                                                    <p>Subtotal ({QuantityPerItem} items)</p>
                                                    <p className="font-medium text-gray-900">₹{totalCount.toFixed(2)}</p>
                                                </div>
                                                <div className="flex justify-between text-sm text-gray-600">
                                                    <p>Shipping</p>
                                                    <p className="text-green-600 font-medium">Free</p>
                                                </div>
                                                <div className="flex justify-between text-sm text-gray-600">
                                                    <p>Taxes</p>
                                                    <p className="font-medium text-gray-900">Calculated at checkout</p>
                                                </div>

                                                <div className="border-t border-gray-200 pt-4">
                                                    <div className="flex justify-between text-lg font-bold text-gray-900">
                                                        <p>Total</p>
                                                        <p className="text-indigo-600">₹{totalCount.toFixed(2)}</p>
                                                    </div>
                                                    <p className="mt-1 text-xs text-gray-500 text-right">Including all taxes</p>
                                                </div>

                                                <button
                                                    onClick={handleOrder}
                                                    className="mt-6 w-full flex items-center justify-center rounded-xl bg-indigo-600 px-6 py-4 text-base font-bold text-white shadow-lg hover:bg-indigo-700 hover:shadow-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 transition-all duration-200 transform hover:-translate-y-0.5"
                                                >
                                                    Place Order
                                                    <svg className="ml-2 w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8l4 4m0 0l-4 4m4-4H3" />
                                                    </svg>
                                                </button>

                                                <div className="mt-4 text-center">
                                                    <Link to='/' className="inline-flex items-center text-sm text-gray-500 hover:text-indigo-600 transition-colors">
                                                        <span className="mr-1">←</span> Continue Shopping
                                                    </Link>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* Security Badge */}
                                <div className="mt-6 flex items-center justify-center gap-2 text-xs text-gray-500">
                                    <svg className="w-4 h-4 text-green-500" fill="currentColor" viewBox="0 0 20 20">
                                        <path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" />
                                    </svg>
                                    <span>Secure SSL Encryption</span>
                                    <span className="mx-2">•</span>
                                    <span>256-bit Security</span>
                                </div>
                            </div>
                        </div>

                    </div>
                </div>
            </div>
        </>
    )
}