import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux'
import { useForm } from "react-hook-form"
import { UpdateUserAsync, selectUserInfo } from '../userSlice';
import { 
    TrashIcon, 
    PencilSquareIcon, 
    PlusCircleIcon,
    MapPinIcon,
    UserCircleIcon,
    EnvelopeIcon,
    ShieldCheckIcon,
    XMarkIcon,
    CheckIcon
} from '@heroicons/react/24/outline'
import { useAlert } from 'react-alert'

export function UserProfile() {
    const userInfo = useSelector(selectUserInfo);
    const dispatch = useDispatch()
    const [handleIndex, sethandleIndex] = useState(-1);
    const [handleAddshow, sethandleAddshow] = useState(false);
    const {
        register, handleSubmit, reset, setValue, formState: { errors },
    } = useForm();
    const alert = useAlert()

    const handleEdit = (newAddress, index) => {
        const newUser = { ...userInfo, addresses: [...userInfo.addresses] };
        newUser.addresses.splice(index, 1, newAddress);
        dispatch(UpdateUserAsync(newUser))
        sethandleIndex(-1);
        alert.success("Address updated successfully")
    }

    const handleDelete = (e, index) => {
        const newUser = { ...userInfo, addresses: [...userInfo.addresses] }
        newUser.addresses.splice(index, 1);
        dispatch(UpdateUserAsync(newUser))
        alert.show("Address deleted")
    }

    const handleEditForm = (index) => {
        sethandleIndex(index);
        const addr = userInfo.addresses[index];
        setValue('fullname', addr.fullname)
        setValue('email', addr.email)
        setValue('phone', addr.phone)
        setValue('country', addr.country)
        setValue('streetaddress', addr.streetaddress)
        setValue('city', addr.city)
        setValue('state', addr.state)
        setValue('postalcode', addr.postalcode)
    }

    const handleAddAddress = (newAddress) => {
        const newUser = { ...userInfo, addresses: [...userInfo.addresses, newAddress] }
        dispatch(UpdateUserAsync(newUser));
        alert.success("New address added")
        sethandleAddshow(false)
        reset();
    }

    const cancelEdit = () => {
        sethandleIndex(-1);
        sethandleAddshow(false);
        reset();
    }

    // Reusable form component for add/edit
    const AddressForm = ({ onSubmit, onCancel, defaultValues = {}, title, subtitle }) => (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-fadeIn">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] overflow-y-auto animate-slideUp">
                <div className="sticky top-0 bg-white border-b border-gray-100 px-6 py-4 flex items-center justify-between">
                    <div>
                        <h3 className="text-lg font-bold text-gray-900">{title}</h3>
                        <p className="text-sm text-gray-500">{subtitle}</p>
                    </div>
                    <button 
                        onClick={onCancel}
                        className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                    >
                        <XMarkIcon className="w-5 h-5 text-gray-500" />
                    </button>
                </div>
                
                <form noValidate onSubmit={handleSubmit(onSubmit)} className="p-6 space-y-6">
                    <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
                        <div className="sm:col-span-2">
                            <label className="block text-sm font-medium text-gray-700 mb-2">Full Name</label>
                            <input
                                type="text"
                                {...register("fullname", { required: "Name is required" })}
                                className="w-full rounded-lg border-gray-300 border px-4 py-2.5 focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
                                placeholder="John Doe"
                            />
                            {errors.fullname && <p className="mt-1 text-sm text-red-600">{errors.fullname.message}</p>}
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Email</label>
                            <input
                                type="email"
                                {...register("email", { 
                                    required: "Email is required",
                                    pattern: { value: /\S+@\S+\.\S+/, message: "Invalid email" }
                                })}
                                className="w-full rounded-lg border-gray-300 border px-4 py-2.5 focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
                                placeholder="john@example.com"
                            />
                            {errors.email && <p className="mt-1 text-sm text-red-600">{errors.email.message}</p>}
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Phone</label>
                            <input
                                type="tel"
                                {...register("phone", { required: "Phone is required" })}
                                className="w-full rounded-lg border-gray-300 border px-4 py-2.5 focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
                                placeholder="+91 1234567890"
                            />
                            {errors.phone && <p className="mt-1 text-sm text-red-600">{errors.phone.message}</p>}
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Country</label>
                            <select
                                {...register("country", { required: true })}
                                className="w-full rounded-lg border-gray-300 border px-4 py-2.5 focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all bg-white"
                            >
                                <option value="India">India</option>
                                <option value="Canada">Canada</option>
                                <option value="Taiwan">Taiwan</option>
                            </select>
                        </div>

                        <div className="sm:col-span-2">
                            <label className="block text-sm font-medium text-gray-700 mb-2">Street Address</label>
                            <input
                                type="text"
                                {...register("streetaddress", { required: "Address is required" })}
                                className="w-full rounded-lg border-gray-300 border px-4 py-2.5 focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
                                placeholder="123 Main Street, Apt 4B"
                            />
                            {errors.streetaddress && <p className="mt-1 text-sm text-red-600">{errors.streetaddress.message}</p>}
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">City</label>
                            <input
                                type="text"
                                {...register("city", { required: "City is required" })}
                                className="w-full rounded-lg border-gray-300 border px-4 py-2.5 focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
                                placeholder="Mumbai"
                            />
                            {errors.city && <p className="mt-1 text-sm text-red-600">{errors.city.message}</p>}
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">State</label>
                            <input
                                type="text"
                                {...register("state", { required: "State is required" })}
                                className="w-full rounded-lg border-gray-300 border px-4 py-2.5 focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
                                placeholder="Maharashtra"
                            />
                            {errors.state && <p className="mt-1 text-sm text-red-600">{errors.state.message}</p>}
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Postal Code</label>
                            <input
                                type="text"
                                {...register("postalcode", { required: "Postal code is required" })}
                                className="w-full rounded-lg border-gray-300 border px-4 py-2.5 focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all"
                                placeholder="400001"
                            />
                            {errors.postalcode && <p className="mt-1 text-sm text-red-600">{errors.postalcode.message}</p>}
                        </div>
                    </div>

                    <div className="flex items-center justify-end gap-4 pt-4 border-t border-gray-100">
                        <button 
                            type="button" 
                            onClick={onCancel}
                            className="px-6 py-2.5 text-sm font-medium text-gray-700 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            className="px-6 py-2.5 bg-indigo-600 text-white text-sm font-semibold rounded-lg hover:bg-indigo-700 focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 transition-all shadow-md hover:shadow-lg flex items-center gap-2"
                        >
                            <CheckIcon className="w-4 h-4" />
                            Save Address
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );

    return (
        <div className="min-h-screen bg-gray-50 py-8 sm:py-12">
            <div className="mx-auto max-w-5xl px-4 sm:px-6 lg:px-8">
                
                {/* Profile Header Card */}
                <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden mb-8">
                    <div className="bg-gradient-to-r from-indigo-600 to-purple-600 px-6 py-8 sm:px-10">
                        <div className="flex items-center gap-4">
                            <div className="w-20 h-20 bg-white/20 backdrop-blur rounded-full flex items-center justify-center">
                                <UserCircleIcon className="w-12 h-12 text-white" />
                            </div>
                            <div className="text-white">
                                <h1 className="text-2xl sm:text-3xl font-bold">
                                    {userInfo.name || "New User"}
                                </h1>
                                <div className="flex items-center gap-2 mt-1 text-indigo-100">
                                    <EnvelopeIcon className="w-4 h-4" />
                                    <span className="text-sm">{userInfo.email}</span>
                                </div>
                            </div>
                        </div>
                        
                        {userInfo.role === 'admin' && (
                            <div className="mt-4 inline-flex items-center gap-2 bg-white/20 backdrop-blur px-3 py-1 rounded-full">
                                <ShieldCheckIcon className="w-4 h-4 text-white" />
                                <span className="text-sm font-medium text-white">Administrator</span>
                            </div>
                        )}
                    </div>
                </div>

                {/* Addresses Section */}
                <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
                    <div className="px-6 py-5 border-b border-gray-100 flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-indigo-100 rounded-lg flex items-center justify-center">
                                <MapPinIcon className="w-5 h-5 text-indigo-600" />
                            </div>
                            <div>
                                <h2 className="text-lg font-bold text-gray-900">Saved Addresses</h2>
                                <p className="text-sm text-gray-500">
                                    {userInfo.addresses?.length || 0} address(es) saved
                                </p>
                            </div>
                        </div>
                        
                        <button
                            onClick={() => sethandleAddshow(true)}
                            className="inline-flex items-center gap-2 px-4 py-2.5 bg-indigo-600 text-white text-sm font-medium rounded-lg hover:bg-indigo-700 focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 transition-all shadow-md hover:shadow-lg"
                        >
                            <PlusCircleIcon className="w-5 h-5" />
                            Add New
                        </button>
                    </div>

                    {/* Address List */}
                    <div className="divide-y divide-gray-100">
                        {userInfo.addresses && userInfo.addresses.length > 0 ? (
                            userInfo.addresses.map((address, index) => (
                                <div 
                                    key={index} 
                                    className="p-6 hover:bg-gray-50 transition-colors group"
                                >
                                    {handleIndex === index ? (
                                        <AddressForm 
                                            onSubmit={(data) => handleEdit(data, index)}
                                            onCancel={cancelEdit}
                                            title="Edit Address"
                                            subtitle="Update your address details"
                                        />
                                    ) : (
                                        <div className="flex items-start justify-between gap-4">
                                            <div className="flex-1 grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                <div className="sm:col-span-2">
                                                    <h3 className="text-base font-semibold text-gray-900 flex items-center gap-2">
                                                        {address.fullname}
                                                        {index === 0 && (
                                                            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-800">
                                                                Default
                                                            </span>
                                                        )}
                                                    </h3>
                                                </div>
                                                
                                                <div className="space-y-1">
                                                    <p className="text-sm text-gray-600 flex items-center gap-2">
                                                        <MapPinIcon className="w-4 h-4 text-gray-400" />
                                                        {address.streetaddress}
                                                    </p>
                                                    <p className="text-sm text-gray-600">
                                                        {address.city}, {address.state} {address.postalcode}
                                                    </p>
                                                    <p className="text-sm text-gray-500">{address.country}</p>
                                                </div>

                                                <div className="space-y-1 sm:text-right">
                                                    <p className="text-sm text-gray-600 flex items-center gap-2 sm:justify-end">
                                                        <EnvelopeIcon className="w-4 h-4 text-gray-400" />
                                                        {address.email}
                                                    </p>
                                                    <p className="text-sm text-gray-600">
                                                        {address.phone}
                                                    </p>
                                                </div>
                                            </div>

                                            <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button
                                                    onClick={() => handleEditForm(index)}
                                                    className="p-2 text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                                                    title="Edit address"
                                                >
                                                    <PencilSquareIcon className="w-5 h-5" />
                                                </button>
                                                <button
                                                    onClick={(e) => handleDelete(e, index)}
                                                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                                    title="Delete address"
                                                >
                                                    <TrashIcon className="w-5 h-5" />
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))
                        ) : (
                            <div className="p-12 text-center">
                                <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                    <MapPinIcon className="w-8 h-8 text-gray-400" />
                                </div>
                                <h3 className="text-lg font-medium text-gray-900 mb-1">No addresses saved</h3>
                                <p className="text-gray-500 mb-4">Add your first address to get started</p>
                                <button
                                    onClick={() => sethandleAddshow(true)}
                                    className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-indigo-600 hover:text-indigo-700 hover:bg-indigo-50 rounded-lg transition-colors"
                                >
                                    <PlusCircleIcon className="w-5 h-5" />
                                    Add Address
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Add Address Modal */}
            {handleAddshow && (
                <AddressForm 
                    onSubmit={handleAddAddress}
                    onCancel={cancelEdit}
                    title="Add New Address"
                    subtitle="Enter your address details below"
                />
            )}
        </div>
    );
}