import React, { useState, useEffect } from "react";
import { loadStripe } from "@stripe/stripe-js";
import { Elements } from "@stripe/react-stripe-js";
import CheckOutForm from "./CheckOutForm";
import "./Stripe.css";
import { currentOrder } from "../features/order/orderSlice";
import { useSelector } from "react-redux";
import { ShieldCheckIcon, LockClosedIcon, CreditCardIcon } from '@heroicons/react/24/outline';

// Make sure to call loadStripe outside of a component's render to avoid
// recreating the Stripe object on every render.
const stripePromise = loadStripe("pk_test_51Og7yBSBRLWCmKMo4eIwT9icodIFi88SmOzPTww2PJNpdILdkq0P329u8eDWcVYPtBQT8rP1yOXIBHxQrx7Z5D5H00Vd8DWR0U");

export default function PaymentIntent() {
  const [clientSecret, setClientSecret] = useState("");
  const [loading, setLoading] = useState(true);
  const currentorder = useSelector(currentOrder);

  useEffect(() => {
    // Create PaymentIntent as soon as the page loads
    fetch("/create-payment-intent", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ totalAmount: currentorder.totalAmount.toFixed(2) }),
    })
      .then((res) => res.json())
      .then((data) => {
        setClientSecret(data.clientSecret);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Payment intent error:", err);
        setLoading(false);
      });
  }, [currentorder]);

  const appearance = {
    theme: 'stripe',
    variables: {
      colorPrimary: '#4f46e5',
      colorBackground: '#ffffff',
      colorText: '#1f2937',
      colorDanger: '#ef4444',
      borderRadius: '8px',
    },
  };

  const options = {
    clientSecret,
    appearance,
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="flex flex-col items-center gap-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
          <p className="text-gray-600 font-medium">Initializing secure payment...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-3xl mx-auto">
        {/* Header Section */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-indigo-100 mb-4">
            <CreditCardIcon className="w-8 h-8 text-indigo-600" />
          </div>
          <h1 className="text-3xl font-bold text-gray-900 mb-2">Secure Payment</h1>
          <p className="text-gray-600">Complete your purchase securely with Stripe</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
          {/* Left Column - Order Summary */}
          <div className="lg:col-span-2 order-2 lg:order-1">
            <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden sticky top-8">
              <div className="bg-gray-900 px-6 py-4">
                <h2 className="text-lg font-bold text-white flex items-center gap-2">
                  <LockClosedIcon className="w-5 h-5" />
                  Order Summary
                </h2>
              </div>
              
              <div className="p-6 space-y-4">
                <div className="flex justify-between items-center py-3 border-b border-gray-100">
                  <span className="text-gray-600">Order ID</span>
                  <span className="text-sm font-mono text-gray-900">#{currentorder?.id?.slice(-8)}</span>
                </div>
                
                <div className="flex justify-between items-center py-3 border-b border-gray-100">
                  <span className="text-gray-600">Items</span>
                  <span className="font-medium text-gray-900">{currentorder?.quantity} items</span>
                </div>

                <div className="flex justify-between items-center py-3 border-b border-gray-100">
                  <span className="text-gray-600">Payment Method</span>
                  <span className="font-medium text-indigo-600">Credit Card</span>
                </div>

                <div className="pt-4">
                  <div className="flex justify-between items-end">
                    <span className="text-gray-900 font-semibold">Total Amount</span>
                    <div className="text-right">
                      <span className="text-3xl font-bold text-indigo-600">
                        ₹{currentorder?.totalAmount?.toFixed(2)}
                      </span>
                      <p className="text-xs text-gray-500 mt-1">Including all taxes</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Security Badges */}
              <div className="bg-gray-50 px-6 py-4 border-t border-gray-200">
                <div className="flex items-center justify-center gap-4 text-xs text-gray-600">
                  <div className="flex items-center gap-1">
                    <ShieldCheckIcon className="w-4 h-4 text-green-500" />
                    <span>SSL Secure</span>
                  </div>
                  <span className="text-gray-300">|</span>
                  <div className="flex items-center gap-1">
                    <LockClosedIcon className="w-4 h-4 text-green-500" />
                    <span>256-bit Encryption</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Right Column - Payment Form */}
          <div className="lg:col-span-3 order-1 lg:order-2">
            <div className="bg-white rounded-2xl shadow-lg border border-gray-200 overflow-hidden">
              <div className="p-6 sm:p-8">
                <div className="mb-6">
                  <h3 className="text-lg font-semibold text-gray-900 mb-1">Card Details</h3>
                  <p className="text-sm text-gray-500">Enter your card information to complete the payment</p>
                </div>

                {clientSecret ? (
                  <Elements stripe={stripePromise} options={options}>
                    <CheckOutForm />
                  </Elements>
                ) : (
                  <div className="text-center py-8">
                    <p className="text-red-600">Unable to initialize payment. Please try again.</p>
                  </div>
                )}
              </div>
            </div>

            {/* Trust Indicators */}
            <div className="mt-6 grid grid-cols-3 gap-4 text-center">
              <div className="flex flex-col items-center">
                <div className="w-12 h-12 rounded-full bg-green-100 flex items-center justify-center mb-2">
                  <ShieldCheckIcon className="w-6 h-6 text-green-600" />
                </div>
                <span className="text-xs font-medium text-gray-600">PCI Compliant</span>
              </div>
              <div className="flex flex-col items-center">
                <div className="w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center mb-2">
                  <LockClosedIcon className="w-6 h-6 text-blue-600" />
                </div>
                <span className="text-xs font-medium text-gray-600">Secure Checkout</span>
              </div>
              <div className="flex flex-col items-center">
                <div className="w-12 h-12 rounded-full bg-purple-100 flex items-center justify-center mb-2">
                  <CreditCardIcon className="w-6 h-6 text-purple-600" />
                </div>
                <span className="text-xs font-medium text-gray-600">Stripe Protected</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}