import React, { useEffect, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { fLoginUserOrderAsync, selectUserInfo, selectUserOrders, selectUserorderStatus } from '../userSlice';
import { FidgetSpinner } from 'react-loader-spinner'
import { Link } from 'react-router-dom';
import { 
    ShoppingBagIcon, 
    MapPinIcon, 
    CreditCardIcon, 
    CalendarIcon, 
    CheckCircleIcon, 
    ClockIcon,
    TruckIcon,
    ArrowDownTrayIcon,
    ChevronRightIcon
} from '@heroicons/react/24/outline';

const statusConfig = {
    'pending': { color: 'yellow', icon: ClockIcon, label: 'Pending' },
    'processing': { color: 'blue', icon: ShoppingBagIcon, label: 'Processing' },
    'shipped': { color: 'indigo', icon: TruckIcon, label: 'Shipped' },
    'delivered': { color: 'green', icon: CheckCircleIcon, label: 'Delivered' },
    'cancelled': { color: 'red', icon: ClockIcon, label: 'Cancelled' }
};

export const UserOrder = () => {
    const dispatch = useDispatch()
    const userInfo = useSelector(selectUserInfo)
    const orders = useSelector(selectUserOrders);
    const orderStatus = useSelector(selectUserorderStatus);
    const [expandedOrder, setExpandedOrder] = useState(null);

    useEffect(() => {
        dispatch(fLoginUserOrderAsync(userInfo.id))
    }, [dispatch, userInfo.id])

    if (orderStatus === 'loading') {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center">
                <div className="flex flex-col items-center gap-4">
                    <FidgetSpinner
                        visible={true}
                        height="120"
                        width="120"
                        ariaLabel="loading"
                        wrapperClass="dna-wrapper"
                        ballColors={['#4f46e5', '#7c3aed', '#2563eb']}
                        backgroundColor="#F4442E"
                    />
                    <p className="text-gray-600 font-medium animate-pulse">Loading your orders...</p>
                </div>
            </div>
        );
    }

    if (!orders || orders.length === 0) {
        return (
            <div className="min-h-screen bg-gray-50 flex items-center justify-center px-4">
                <div className="text-center max-w-md">
                    <div className="w-24 h-24 bg-gray-200 rounded-full flex items-center justify-center mx-auto mb-6">
                            <ShoppingBagIcon className="w-12 h-12 text-gray-400" />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-2">No Orders Yet</h2>
                    <p className="text-gray-600 mb-6">Looks like you haven't placed any orders yet. Start shopping to see your orders here!</p>
                    <Link 
                        to="/" 
                        className="inline-flex items-center justify-center px-6 py-3 bg-indigo-600 text-white font-semibold rounded-xl hover:bg-indigo-700 transition-colors shadow-lg hover:shadow-xl"
                    >
                        Start Shopping
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 py-8 sm:py-12">
            <div className="mx-auto max-w-5xl px-4 sm:px-6 lg:px-8">
                {/* Header */}
                <div className="mb-8">
                    <h1 className="text-3xl sm:text-4xl font-bold text-gray-900 mb-2">My Orders</h1>
                    <p className="text-gray-600">Track and manage your orders</p>
                </div>

                {/* Orders List */}
                <div className="space-y-6">
                    {orders.map((order) => {
                        const status = statusConfig[order.status] || statusConfig['pending'];
                        const StatusIcon = status.icon;
                        const isExpanded = expandedOrder === order.id;
                        
                        return (
                            <div 
                                key={order.id} 
                                className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden hover:shadow-md transition-shadow duration-300"
                            >
                                {/* Order Header */}
                                <div className="p-6 border-b border-gray-100">
                                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                                        <div className="flex items-center gap-4">
                                            <div className={`w-12 h-12 rounded-xl bg-${status.color}-100 flex items-center justify-center`}>
                                                <StatusIcon className={`w-6 h-6 text-${status.color}-600`} />
                                            </div>
                                            <div>
                                                <div className="flex items-center gap-3 mb-1">
                                                    <h3 className="text-lg font-bold text-gray-900">Order #{order.id}</h3>
                                                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-${status.color}-100 text-${status.color}-800`}>
                                                        {status.label}
                                                    </span>
                                                </div>
                                                <p className="text-sm text-gray-500 flex items-center gap-1">
                                                    <CalendarIcon className="w-4 h-4" />
                                                    Placed on {new Date(order.createdAt).toLocaleDateString('en-US', { 
                                                        year: 'numeric', 
                                                        month: 'long', 
                                                        day: 'numeric' 
                                                    })}
                                                </p>
                                            </div>
                                        </div>
                                        
                                        <div className="flex items-center gap-3">
                                            <Link to={`/Invoice/${order.id}`}>
                                                <button className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium text-indigo-600 bg-indigo-50 rounded-lg hover:bg-indigo-100 transition-colors">
                                                    <ArrowDownTrayIcon className="w-4 h-4" />
                                                    Invoice
                                                </button>
                                            </Link>
                                            <button 
                                                onClick={() => setExpandedOrder(isExpanded ? null : order.id)}
                                                className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                                            >
                                                <ChevronRightIcon className={`w-5 h-5 transform transition-transform duration-200 ${isExpanded ? 'rotate-90' : ''}`} />
                                            </button>
                                        </div>
                                    </div>
                                </div>

                                {/* Order Summary Bar */}
                                <div className="px-6 py-4 bg-gray-50 border-b border-gray-100">
                                    <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 text-sm">
                                        <div>
                                            <p className="text-gray-500 mb-1">Total Amount</p>
                                            <p className="font-bold text-gray-900 text-lg">₹{order.totalAmount.toFixed(2)}</p>
                                        </div>
                                        <div>
                                            <p className="text-gray-500 mb-1">Items</p>
                                            <p className="font-semibold text-gray-900">{order.quantity} items</p>
                                        </div>
                                        <div>
                                            <p className="text-gray-500 mb-1">Payment</p>
                                            <p className="font-semibold text-gray-900 flex items-center gap-1">
                                                <CreditCardIcon className="w-4 h-4" />
                                                {order.Payment}
                                            </p>
                                        </div>
                                        <div>
                                            <p className="text-gray-500 mb-1">Status</p>
                                            <p className={`font-semibold text-${status.color}-600`}>{status.label}</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Expandable Details */}
                                {isExpanded && (
                                    <div className="p-6 space-y-6 animate-fadeIn">
                                        {/* Products List */}
                                        <div>
                                            <h4 className="text-sm font-semibold text-gray-900 uppercase tracking-wider mb-4">Order Items</h4>
                                            <div className="space-y-4">
                                                {order.products.map((item) => (
                                                    <div 
                                                        key={item.id} 
                                                        className="flex gap-4 p-4 bg-gray-50 rounded-xl hover:bg-gray-100 transition-colors"
                                                    >
                                                        <div className="h-20 w-20 flex-shrink-0 overflow-hidden rounded-lg border border-gray-200 bg-white">
                                                            <img
                                                                src={item.product.thumbnail}
                                                                alt={item.product.title}
                                                                className="h-full w-full object-cover object-center"
                                                            />
                                                        </div>
                                                        <div className="flex-1 flex flex-col justify-center">
                                                            <h5 className="text-sm font-semibold text-gray-900 mb-1">
                                                                {item.product.title}
                                                            </h5>
                                                            <p className="text-xs text-gray-500 mb-2">{item.product.brand}</p>
                                                            <div className="flex items-center justify-between">
                                                                <span className="text-sm text-gray-600">Qty: {item.quantity}</span>
                                                                <span className="text-sm font-bold text-gray-900">₹{item.product.price.toFixed(2)}</span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>

                                        {/* Shipping Address */}
                                        <div>
                                            <h4 className="text-sm font-semibold text-gray-900 uppercase tracking-wider mb-4 flex items-center gap-2">
                                                <MapPinIcon className="w-4 h-4" />
                                                Shipping Address
                                            </h4>
                                            {order.SelectedAddress && order.SelectedAddress.map((addr, idx) => (
                                                <div key={idx} className="bg-gray-50 rounded-xl p-4 border border-gray-200">
                                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                                        <div>
                                                            <p className="text-sm font-semibold text-gray-900">{addr.fullname}</p>
                                                            <p className="text-sm text-gray-600 mt-1">{addr.streetaddress}</p>
                                                            <p className="text-sm text-gray-600">{addr.city}, {addr.state} {addr.postalcode}</p>
                                                        </div>
                                                        <div className="sm:text-right">
                                                            <p className="text-sm text-gray-600 flex items-center gap-2 sm:justify-end">
                                                                <span className="font-medium">Phone:</span> {addr.phone}
                                                            </p>
                                                            <p className="text-sm text-gray-600 mt-1">{addr.email}</p>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                {/* Quick Preview (when collapsed) */}
                                {!isExpanded && (
                                    <div className="px-6 py-4">
                                        <div className="flex items-center gap-2 overflow-x-auto pb-2">
                                            {order.products.slice(0, 4).map((item, idx) => (
                                                <div key={idx} className="flex-shrink-0 w-12 h-12 rounded-lg border border-gray-200 overflow-hidden">
                                                    <img
                                                        src={item.product.thumbnail}
                                                        alt=""
                                                        className="w-full h-full object-cover"
                                                    />
                                                </div>
                                            ))}
                                            {order.products.length > 4 && (
                                                <div className="flex-shrink-0 w-12 h-12 rounded-lg bg-gray-100 flex items-center justify-center text-xs font-medium text-gray-600">
                                                    +{order.products.length - 4}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    )
}